import{_ as o,o as l,c as a,a5 as t}from"./chunks/framework.BPFk9-tb.js";const S=JSON.parse('{"title":"Solon 实用教程 —— 介绍","description":"","frontmatter":{"date":"2025-02-05T21:08:21","title":"Solon 实用教程 —— 介绍","categories":["教程100","写作","Solon","Solon 实用教程"],"tags":["教程100","写作","Solon","Solon 实用教程"]},"headers":[{"level":2,"title":"说明","slug":"说明","link":"#说明","children":[]},{"level":2,"title":"Solon 是什么","slug":"solon-是什么","link":"#solon-是什么","children":[{"level":3,"title":"项目简介","slug":"项目简介","link":"#项目简介","children":[]},{"level":3,"title":"项目特点","slug":"项目特点","link":"#项目特点","children":[{"level":4,"title":"技术价值","slug":"技术价值","link":"#技术价值","children":[]},{"level":4,"title":"业务价值","slug":"业务价值","link":"#业务价值","children":[]},{"level":4,"title":"生态价值","slug":"生态价值","link":"#生态价值","children":[]}]}]},{"level":2,"title":"为什么要学 Solon","slug":"为什么要学-solon","link":"#为什么要学-solon","children":[]},{"level":2,"title":"教程内容","slug":"教程内容","link":"#教程内容","children":[]}],"relativePath":"posts/course100/014.md","filePath":"posts/course100/014.md"}'),r={name:"posts/course100/014.md"};function n(i,e,s,h,p,c){return l(),a("div",null,[...e[0]||(e[0]=[t('<h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>一次在 Jfinal 的群聊中，无意中发现 Solon 的，说「 Solon只需要几M」。于是搜索到官网，看了官网内容。抱着试一试的态度，于是按着官方文档写例子，发现挺好用的，生态也很完整，自己想要的东西基本都有。</p><p>目前自己在尝试构建 Solon 版的快速开发框架，算是学习环境。在公司使用 Solon 和 Solon Cloud 开发安全运营平台，算是实践环境。</p><p>在学习实践 Solon 的过程中，也是会碰到问题的，我就会把问题和处理过程记录下来。本着「教是最好的学」的原则，于是整理本教程《Solon 实用教程》，以便自己能更好的理解和使用 Solon。</p><p>由于我还在学习和实践 Solon 的过程中，因此本教程会持续更新。同时，由于我的学习可能不够深入或使用不当，教程中难免会出现错误，欢迎大家指正。</p><h2 id="solon-是什么" tabindex="-1">Solon 是什么 <a class="header-anchor" href="#solon-是什么" aria-label="Permalink to &quot;Solon 是什么&quot;">​</a></h2><p>以下是Solon在开放原子开源基金会的<a href="https://www.openatom.cn/project/YNjOOt50Swn2" target="_blank" rel="noreferrer">介绍</a>（<a href="https://www.openatom.cn/project/YNjOOt50Swn2%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://www.openatom.cn/project/YNjOOt50Swn2）。</a></p><h3 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h3><p>Solon 一个是新的Java “生态型”应用开发框架。相对目前主流解决方案。Solon并发高 2～ 3 倍；内存省 50%；启动快 5 ～ 10 倍；打包小 50% ~ 90%；同时兼容 java8 ~ java22 运行时。</p><h3 id="项目特点" tabindex="-1">项目特点 <a class="header-anchor" href="#项目特点" aria-label="Permalink to &quot;项目特点&quot;">​</a></h3><h4 id="技术价值" tabindex="-1">技术价值 <a class="header-anchor" href="#技术价值" aria-label="Permalink to &quot;技术价值&quot;">​</a></h4><p>Solon 提供了更高的计算性价比；更好的软件开发效率；快的生产与部署体验；更灵活的兼容选择。</p><h4 id="业务价值" tabindex="-1">业务价值 <a class="header-anchor" href="#业务价值" aria-label="Permalink to &quot;业务价值&quot;">​</a></h4><p>Solon解决了Spring 的历史包袱重，架构臃肿，计算资源浪费，学习曲线复杂，以及不再支持java17之前版本等问题。</p><h4 id="生态价值" tabindex="-1">生态价值 <a class="header-anchor" href="#生态价值" aria-label="Permalink to &quot;生态价值&quot;">​</a></h4><p>Solon 给Java 生态整合提供了更先进的底座支持。灵活的架构，即可适配传统的java-ee体系，又可以支持最新的技术发展成果。</p><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=ZjVhMDI1OWI2NTQzODk2MGE2MjY0M2I2ZWQ5ZDY1MmZfTHNhRURJV0tmMEFHbmJuaXp1N0E3d3ppNXl6ejVDbVhfVG9rZW46Skl4U2JMREJGb3RzQzR4MlF1N2N6OTNhbmNiXzE3Mzg3NjA5ODY6MTczODc2NDU4Nl9WNA" alt="img"></p><h2 id="为什么要学-solon" tabindex="-1">为什么要学 Solon <a class="header-anchor" href="#为什么要学-solon" aria-label="Permalink to &quot;为什么要学 Solon&quot;">​</a></h2><ul><li>更快、更小、更简单。Solon并发高 2～ 3 倍；启动快 5 ～ 10 倍；打包小 50% ~ 90%；内存省 50%；最小 Web 完整开发单位 1Mb。除了注解模式之外，还可以按需手动，生态丰富，选择自由。同时兼容 java8 ~ java22 运行时。</li><li>国产框架，生态完整。随着国产信创的推荐，使用国产框架将更有优势。</li><li>交流方便，容易理解。有官方的沟通交流群和使用 Gitee，沟通交流方面，文档使用中文编写，容易理解。</li></ul><h2 id="教程内容" tabindex="-1">教程内容 <a class="header-anchor" href="#教程内容" aria-label="Permalink to &quot;教程内容&quot;">​</a></h2><p>在学习和实践 Solon 的过程中，会发现自己一开始更关注怎么用？接着才会关注为什么要这么用？之后才会想这样设计的好处？如何用 Solon 进行 Web 开发是本教程的主线，本教程不会讲解 Solon 的源码。本教程的主要来源为 <a href="https://solon.noear.org/article/learn-start" target="_blank" rel="noreferrer">Solon 官网</a> 、 <a href="https://gitee.com/noear/solon" target="_blank" rel="noreferrer">Solon 源码</a>和自己的实践（<a href="https://gitee.com/CrazyAirhead/projects?sort=&amp;scope=&amp;state=public&amp;search=solon" target="_blank" rel="noreferrer">https://gitee.com/CrazyAirhead/projects?sort=&amp;scope=&amp;state=public&amp;search=solon</a> 和 <a href="https://gitee.com/CrazyAirhead/porpoise-demo%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://gitee.com/CrazyAirhead/porpoise-demo）。</a></p><p>本教程主要以下几个部分：</p><ul><li>初识 Solon</li><li>数据操作</li><li>Web 开发</li><li>Solon Boot</li><li>Solon Cloud</li></ul><p>本教程使用 IDEA、JDK17 和 Gradle，需要有这些基础知识。本教程于官网资料的主要不同在于，官网面向的读者更宽泛，会涉及各种不同版本 JDK，Maven 和 Gradle 的配置，不同的编程习惯，比如注解或手动获取 Bean 等，不同的技术偏好，比如多种 ORM 组件等。本教程则更面向实践，并限定了选择，这样可以比较快速简单的入门，实际使用 Solon 进行开发工作。</p>',24)])])}const u=o(r,[["render",n]]);export{S as __pageData,u as default};
